-- Lebensmittel-Katalog erweitern (Teil 2 der Katalog-Umstellung)
--
-- Voraussetzung: supabase/nutrition_catalog_migration.sql ist eingespielt.
--
-- * Entfernt den Katalogeintrag "Ungesüßte Pflanzendrinks" (seed_id 212). Er wird
--   nur als gelöscht markiert (deleted_at). Hängt noch ein Rezept an ihm, bricht
--   die Migration vorher ab, damit keine Zutat still verloren geht.
-- * Legt 400 neue Katalogeinträge an (seed_id 318..717): deine Erweiterungsliste
--   (366) plus 34 Light-/Normal-Ergänzungen bei Milchprodukten und Co.
--   Die Nährwerte sind Richtwerte pro 100 g bzw. 100 ml (Reis/Hülsenfrüchte
--   gekocht, Nudeln/Körner/Mehle trocken, wie bei den bestehenden Einträgen),
--   keine geprüften Tabellenwerte. Tags, glutenfrei/laktosefrei und Ernährungsform
--   sind aus den Werten bzw. Allergenen abgeleitet.
--
-- Ausführen:
--   docker exec -i supabase-db psql -U postgres -d postgres -v ON_ERROR_STOP=1 \
--     < nutrition_catalog_expansion_migration.sql
-- Läuft in einer Transaktion und ist wiederholbar.

begin;

do $$
declare n int;
begin
  select count(*) into n
  from public.nut_recipes r
  where r.deleted_at is null
    and exists (
      select 1 from jsonb_array_elements(r.ingredients) i
      where jsonb_typeof(i->'foodId') = 'number' and (i->>'foodId')::int = 212);
  if n > 0 then
    raise exception 'Abbruch: % Rezept(e) verwenden noch "Ungesüßte Pflanzendrinks" (seed_id 212). Zutat dort ersetzen und erneut ausführen.', n;
  end if;
end $$;

update public.nut_foods
set deleted_at = now()
where deleted_at is null
  and ((owner_id is null and seed_id = 212 and name = 'Ungesüßte Pflanzendrinks')
    or override_of = 212);

insert into public.nut_foods
  (seed_id, name, food_group, category, unit, kcal, protein, carbs, sugar, fat, satfat, fiber, salt,
   vitamins, minerals, micros_other, allergens, glutenfrei, laktosefrei, tags, diet)
